WHERE r.member_id = #{memberId}


  AND r.status = #{status}



  AND c.title LIKE CONCAT('%', #{keyword}, '%')



  AND r.created_at >= #{from}



  AND r.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)






      AND CURRENT_TIMESTAMP < p.starts_at



      AND p.starts_at <= CURRENT_TIMESTAMP
      AND CURRENT_TIMESTAMP < p.ends_at



      AND p.ends_at <= CURRENT_TIMESTAMP
